(()=>{document.querySelectorAll(".details").forEach(l=>{let a=l.querySelector("[data-expand-all]"),c=l.querySelector("[data-collapse-all]"),t=l.querySelectorAll("details");a.addEventListener("click",()=>{t.forEach(e=>e.open=!0)}),c.addEventListener("click",()=>{t.forEach(e=>e.open=!1)}),t.forEach(e=>{e.addEventListener("toggle",()=>{let n=e.open?`#${e.id}`:"#";history.replaceState(null,"",n)})})});var o=window.location.hash.slice(1);if(o){let l=document.querySelector(`.details #${CSS.escape(o)}`);l&&(l.open=!0)}})();